import { getDashboardData } from './lib/data'

export async function CardStats() {
  const { totalRevenue, totalInvoices } = await getDashboardData()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
