import { Suspense } from 'react'
import { RevenueChart, RevenueChartSkeleton } from './RevenueChart'
import { LatestInvoices, LatestInvoicesSkeleton } from './LatestInvoices'
import { CardStats, CardStatsSkeleton } from './CardStats'

// The page itself does no async work, so the heading and the Suspense
// fallbacks are all part of the prerendered static shell. Each section
// streams in independently at request time.
export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStats />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChart />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoices />
      </Suspense>
    </main>
  )
}

